{
    void *map = mmap(0, data_size, 0x1 | 0x2, 0x01 | 0x20, 0, 0);
    if (map == ((void *)-1))
    {
        fprintf(stderr, "could map anonymous memory of size %ld\n", data_size);
        return -1;
    }
    *data = (uint8_t *)map;
    return 0;
}

functions.unmap:
int unmap(const uint8_t *data, size_t data_size)
{
    if (munmap((void *)data, data_size) < 0)
